add_filter( 'woocommerce_account_menu_items', 'perfectpixel_account_tab_to_url_menu', 45 );
add_filter( 'woocommerce_get_endpoint_url', 'perfectpixel_account_tab_to_url_link', 10, 2 );

function perfectpixel_account_tab_to_url_menu( $items ) {
	$after = trim( '{{account_link_after}}' );
	$new   = array();
	foreach ( $items as $key => $label ) {
		$new[ $key ] = $label;
		if ( $key === $after ) {
			$new['perfectpixel-link'] = '{{account_link_label}}';
		}
	}
	if ( ! isset( $new['perfectpixel-link'] ) ) {
		$new = array_slice( $new, 0, -1, true ) + array( 'perfectpixel-link' => '{{account_link_label}}' ) + array_slice( $new, -1, null, true );
	}
	return $new;
}

function perfectpixel_account_tab_to_url_link( $url, $endpoint ) {
	if ( 'perfectpixel-link' !== $endpoint ) {
		return $url;
	}
	$target = trim( '{{account_link_url}}' );
	return 0 === strpos( $target, '/' ) ? home_url( $target ) : esc_url_raw( $target );
}
